  if (baseEnc !== 'Builtin') for (let c = 32; c < 256; c++) codeMap.set(c, baseEnc === 'MacRomanEncoding' && c >= 128 ? MAC_ROMAN_HI[c - 128] || '' : winAnsiToUnicode(c));
