    const diff = doc.getArray(enc, 'Differences') || [];
    let code = 0;
    for (const d of diff) { const v = doc.resolve<PdfObj>(d); if (typeof v === 'number') code = v; else if (isName(v)) { codeMap.set(code, glyphToUnicode(v.name)); code++; } }
